// 课外阅读 (graded readers) data API. Books live in src/data/reading/{key}.json
// (generated by scripts/convert_reading.py), lazy-loaded one chunk per book.
// meta.json is tiny and static, so the shelf and the home row render without loading a book.
// The glob pattern requires a dash so reading/meta.json is excluded.

import meta from "./reading/meta.json"; // { "tiantiandu-2b": { title, level, chars, vocab, lessons:[{n,title,en,chars,vocab}] } }

const loaders = import.meta.glob("./reading/*-*.json");

export const readingBooks = Object.entries(meta).map(([key, b]) => ({ key, ...b }));

const _cache = new Map();
export function loadReadingBook(key) {
  if (_cache.has(key)) return _cache.get(key);
  const loader = loaders[`./reading/${key}.json`];
  const p = loader ? loader().then((m) => m.default) : Promise.resolve(null);
  _cache.set(key, p);
  return p;
}
